import {
  Directive,
  ElementRef,
  HostBinding,
  HostListener,
  Input,
  booleanAttribute,
  inject,
  numberAttribute,
  DOCUMENT,
} from '@angular/core';
import { QAnalyticsService } from '@questrade/allspark-angular-components/core/services';
import { QLinkClickAnalyticsEvent } from './types/link-click-analytics-event.type';
import { QLinkSize } from './types/link-size.type';
import { QLinkVariant } from './types/link-variant.type';

@Directive({ selector: 'a[qLink], a[q-link]' })
export class QLinkDirective {
  @Input() variant: QLinkVariant = 'primary';
  @Input() size: QLinkSize = 'auto';
  @Input({ transform: booleanAttribute }) underlined = false;
  @Input({ transform: booleanAttribute }) disabled = false;
  @Input({ transform: numberAttribute }) tabindex: number | null = null;
  @Input({ transform: booleanAttribute }) analyticsCssClassIdentifier = true;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-link';

  @HostBinding('attr.tabindex') get _hostTabindex(): number | null {
    return this.disabled ? -1 : this.tabindex;
  }

  @HostBinding('class') get _hostClass(): string {
    return [
      'q-link',
      `q-link-variant-${this.variant}`,
      `q-link-size-${this.size}`,
      this.underlined && 'q-link-underlined',
      this.disabled && `q-link-disabled`,
      'q-focus-indicator',
      this._analytics.isEnabled && this.analyticsCssClassIdentifier && 'q-analytics',
    ]
      .filter(Boolean)
      .join(' ');
  }

  @HostListener('click', ['$event']) _onClick(event: MouseEvent): void {
    this._sendAnalyticsEvent(this._elementRef.nativeElement);

    if (this.disabled) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  }

  private readonly _elementRef = inject(ElementRef);
  private readonly _window = inject(DOCUMENT).defaultView;
  private readonly _analytics = inject(QAnalyticsService);

  private _sendAnalyticsEvent(hostElement: HTMLAnchorElement): void {
    const siteHost = this._window?.location.host;
    const linkHost = hostElement.host;
    let eventName:
      | 'link_click_navigation'
      | 'link_click_outbound_to_questrade'
      | 'link_click_outbound';

    if (linkHost === siteHost) {
      eventName = 'link_click_navigation';
    } else if (linkHost.includes('questrade')) {
      eventName = 'link_click_outbound_to_questrade';
    } else {
      eventName = 'link_click_outbound';
    }

    const analyticsEvent: QLinkClickAnalyticsEvent = {
      event: eventName,
      link_text: hostElement.innerText,
      link_classes: hostElement.classList.value,
      link_url: hostElement.href,
    };
    if (eventName.includes('outbound')) {
      analyticsEvent.outbound = true;
    }
    this._analytics.sendEvent(analyticsEvent);
  }
}
